import sys
lines = sys.stdin.read().splitlines()
if lines:
    parts = lines[0].split()
    m, n, k = int(parts[0]), int(parts[1]), int(parts[2])
    board = [lines[1+i].split() for i in range(m)]
    words = lines[1+m].split()
    trie = {}
    for w in words:
        node = trie
        for c in w:
            node = node.setdefault(c, {})
        node['$'] = w
    found = set()
    def dfs(r, c, parent):
        ch = board[r][c]
        if ch not in parent: return
        curr = parent[ch]
        if '$' in curr: found.add(curr['$'])
        board[r][c] = '#'
        for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and board[nr][nc] != '#':
                dfs(nr, nc, curr)
        board[r][c] = ch
    for r in range(m):
        for c in range(n):
            dfs(r, c, trie)
    print(' '.join(sorted(list(found))))
